css:
*{
  font-family: sans-serif;
  font-size: 15px;
  box-sizing: border-box;
  text-align: justify;
  padding: 0;
  margin: 0;
}

.s2{
    padding-top: 4.4cm;
}

.s3{
    padding-top: 4cm;
}
.logo-container{
    width: 100%;
    display: flex;
}

.logo-left-margin{
    width: 100%;
    height: 100px;
}

.meril{
  width: 150px;
  font-family: sans-serif;
}
.print-format{
    margin: 0;
    padding: 0;
}
h4{
  text-align: center;
  padding: 0.2cm;
  margin-top: 0.1cm;
  color: #fff !important;
  background: #5291cd;
}
article{
  padding: 0cm 2cm;
  page-break-inside: avoid;
  page-break-after: always;
}

h5{
  position: relative;
  font-weight: 500;
  margin: 0.8cm 0;
  font-size: 0.4cm;
}
h5::before{
  content: "1.";
  position: absolute;
  left: -1cm
}
h5[data-num="2"]::before{
     content: "2.";
}
h5[data-num="3"]::before{
     content: "3.";
}
h5[data-num="4"]::before{
     content: "4.";
}
h5[data-num="5"]::before{
     content: "5.";
}
h5[data-num="6"]::before{
     content: "6.";
}
h5[data-num="7"]::before{
     content: "7.";
}
h5[data-num="8"]::before{
     content: "8.";
}
h5[data-num="9"]::before{
     content: "9.";
}
h5[data-num="10"]::before{
     content: "10.";
}

h6{
    text-align: center;
    font-weight: 500;
    font-size: 20px;
    margin-top: 2cm;
}

p{
   text-align: justify;
}

img{
  width: 4cm;
  display: block;
  margin-left: auto;
}
.bottom{
    margin-top: 2cm;
}

@page {
  size: A4 portrait; /* Set page size to A4 and orientation to portrait */
  margin: 2cm; /* Apply a 2cm margin on all sides */
}
